  "sections": [
    {"offset": {"line": 4, "column": 0}, "map": {"version":3,"sources":["file:///D:/FINAL-Ano-Tara/ano-tara/frontend/app/footer/Footer.js"],"sourcesContent":["import Link from \"next/link\";\r\n\r\nexport default function Footer() {\r\n  return (\r\n    <footer className=\"mt-auto border-t border-slate-200 bg-white pt-16 pb-8\">\r\n      <div className=\"mx-auto max-w-6xl px-6 sm:px-12\">\r\n        <div className=\"mb-12 grid grid-cols-1 gap-12 md:grid-cols-4\">\r\n          <div className=\"md:col-span-1\">\r\n            <div className=\"mb-4 flex items-center gap-2\">\r\n              <span className=\"text-xl font-black tracking-tighter text-slate-900 italic\">ano tara?</span>\r\n            </div>\r\n            <p className=\"text-sm leading-relaxed text-slate-500\">\r\n              Kung saan maganda, mahal! We help you discover the perfect destinations tailored for your budget and style. Start your next great adventure with us.\r\n            </p>\r\n          </div>\r\n\r\n\r\n          <div>\r\n            <h4 className=\"mb-4 font-bold text-slate-900\">Explore</h4>\r\n            <ul className=\"space-y-3 text-sm text-slate-500\">\r\n              <li><Link href=\"/destinations\" className=\"transition-colors hover:text-slate-900\">Destinations</Link></li>\r\n              <li><Link href=\"/all-experiences\" className=\"transition-colors hover:text-slate-900\">Experiences</Link></li>\r\n              <li><Link href=\"/predict-outfit\" className=\"transition-colors hover:text-slate-900\">Outfit Tool</Link></li>\r\n              <li><Link href=\"/about\" className=\"transition-colors hover:text-slate-900\">About Us</Link></li>\r\n            </ul>\r\n          </div>\r\n\r\n          <div>\r\n            <h4 className=\"mb-4 font-bold text-slate-900\">Support</h4>\r\n            <ul className=\"space-y-3 text-sm text-slate-500\">\r\n              <li><Link href=\"/faq\" className=\"transition-colors hover:text-slate-900\">FAQ</Link></li>\r\n              <li><Link href=\"/contact\" className=\"transition-colors hover:text-slate-900\">Contact Us</Link></li>\r\n              <li><Link href=\"/privacy\" className=\"transition-colors hover:text-slate-900\">Privacy Policy</Link></li>\r\n              <li><Link href=\"/terms\" className=\"transition-colors hover:text-slate-900\">Terms of Service</Link></li>\r\n            </ul>\r\n          </div>\r\n\r\n          <div>\r\n            <h4 className=\"mb-4 font-bold text-slate-900\">Follow Us</h4>\r\n            <div className=\"mb-6 flex gap-4\">\r\n              <a href=\"#\" aria-label=\"Facebook\" className=\"flex h-10 w-10 items-center justify-center rounded-full bg-slate-100 text-slate-600 transition-colors hover:bg-slate-200 hover:text-slate-900\">\r\n                <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"2\" strokeLinecap=\"round\" strokeLinejoin=\"round\"><path d=\"M18 2h-3a5 5 0 0 0-5 5v3H7v4h3v8h4v-8h3l1-4h-4V7a1 1 0 0 1 1-1h3z\"></path></svg>\r\n              </a>\r\n              <a href=\"#\" aria-label=\"Instagram\" className=\"flex h-10 w-10 items-center justify-center rounded-full bg-slate-100 text-slate-600 transition-colors hover:bg-slate-200 hover:text-slate-900\">\r\n                <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"2\" strokeLinecap=\"round\" strokeLinejoin=\"round\"><rect x=\"2\" y=\"2\" width=\"20\" height=\"20\" rx=\"5\" ry=\"5\"></rect><path d=\"M16 11.37A4 4 0 1 1 12.63 8 4 4 0 0 1 16 11.37z\"></path><line x1=\"17.5\" y1=\"6.5\" x2=\"17.51\" y2=\"6.5\"></line></svg>\r\n              </a>\r\n              <a href=\"#\" aria-label=\"Twitter\" className=\"flex h-10 w-10 items-center justify-center rounded-full bg-slate-100 text-slate-600 transition-colors hover:bg-slate-200 hover:text-slate-900\">\r\n                <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"2\" strokeLinecap=\"round\" strokeLinejoin=\"round\"><path d=\"M22 4s-.7 2.1-2 3.4c1.6 10-9.4 17.3-18 11.6 2.2.1 4.4-.6 6-2C3 15.5.5 9.6 3 5c2.2 2.6 5.6 4.1 9 4-.9-4.2 4-6.6 7-3.8 1.1 0 3-1.2 3-1.2z\"></path></svg>\r\n              </a>\r\n            </div>\r\n            <p className=\"text-sm text-slate-500\">Email: hello@anotara.com</p>\r\n          </div>\r\n        </div>\r\n\r\n        <div className=\"flex flex-col items-center justify-between border-t border-slate-200 pt-8 md:flex-row\">\r\n          <p className=\"text-sm text-slate-400\">\r\n            © {new Date().getFullYear()} Ano Tara. All rights reserved.\r\n          </p>\r\n          <div className=\"mt-4 flex gap-6 md:mt-0\">\r\n            <Link href=\"#\" className=\"text-sm text-slate-400 hover:text-slate-600\">Privacy</Link>\r\n            <Link href=\"#\" className=\"text-sm text-slate-400 hover:text-slate-600\">Terms</Link>\r\n            <Link href=\"#\" className=\"text-sm text-slate-400 hover:text-slate-600\">Cookies</Link>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </footer>\r\n  );\r\n}\r\n"],"names":["Footer","className","href","xmlns","width","height","viewBox","fill","stroke","strokeWidth","strokeLinecap","strokeLinejoin","d","x","y","rx","ry","x1","y1","x2","y2","Date","getFullYear"],"mappings":";;;;;AAAA;;;AAEe,SAASA;IACtB,qBACE,6LAAC;QAAOC,WAAU;kBAChB,cAAA,6LAAC;YAAIA,WAAU;;8BACb,6LAAC;oBAAIA,WAAU;;sCACb,6LAAC;4BAAIA,WAAU;;8CACb,6LAAC;oCAAIA,WAAU;8CACb,cAAA,6LAAC;wCAAKA,WAAU;kDAA4D;;;;;;;;;;;8CAE9E,6LAAC;oCAAEA,WAAU;8CAAyC;;;;;;;;;;;;sCAMxD,6LAAC;;8CACC,6LAAC;oCAAGA,WAAU;8CAAgC;;;;;;8CAC9C,6LAAC;oCAAGA,WAAU;;sDACZ,6LAAC;sDAAG,cAAA,6LAAC,0KAAI;gDAACC,MAAK;gDAAgBD,WAAU;0DAAyC;;;;;;;;;;;sDAClF,6LAAC;sDAAG,cAAA,6LAAC,0KAAI;gDAACC,MAAK;gDAAmBD,WAAU;0DAAyC;;;;;;;;;;;sDACrF,6LAAC;sDAAG,cAAA,6LAAC,0KAAI;gDAACC,MAAK;gDAAkBD,WAAU;0DAAyC;;;;;;;;;;;sDACpF,6LAAC;sDAAG,cAAA,6LAAC,0KAAI;gDAACC,MAAK;gDAASD,WAAU;0DAAyC;;;;;;;;;;;;;;;;;;;;;;;sCAI/E,6LAAC;;8CACC,6LAAC;oCAAGA,WAAU;8CAAgC;;;;;;8CAC9C,6LAAC;oCAAGA,WAAU;;sDACZ,6LAAC;sDAAG,cAAA,6LAAC,0KAAI;gDAACC,MAAK;gDAAOD,WAAU;0DAAyC;;;;;;;;;;;sDACzE,6LAAC;sDAAG,cAAA,6LAAC,0KAAI;gDAACC,MAAK;gDAAWD,WAAU;0DAAyC;;;;;;;;;;;sDAC7E,6LAAC;sDAAG,cAAA,6LAAC,0KAAI;gDAACC,MAAK;gDAAWD,WAAU;0DAAyC;;;;;;;;;;;sDAC7E,6LAAC;sDAAG,cAAA,6LAAC,0KAAI;gDAACC,MAAK;gDAASD,WAAU;0DAAyC;;;;;;;;;;;;;;;;;;;;;;;sCAI/E,6LAAC;;8CACC,6LAAC;oCAAGA,WAAU;8CAAgC;;;;;;8CAC9C,6LAAC;oCAAIA,WAAU;;sDACb,6LAAC;4CAAEC,MAAK;4CAAI,cAAW;4CAAWD,WAAU;sDAC1C,cAAA,6LAAC;gDAAIE,OAAM;gDAA6BC,OAAM;gDAAKC,QAAO;gDAAKC,SAAQ;gDAAYC,MAAK;gDAAOC,QAAO;gDAAeC,aAAY;gDAAIC,eAAc;gDAAQC,gBAAe;0DAAQ,cAAA,6LAAC;oDAAKC,GAAE;;;;;;;;;;;;;;;;sDAE5L,6LAAC;4CAAEV,MAAK;4CAAI,cAAW;4CAAYD,WAAU;sDAC3C,cAAA,6LAAC;gDAAIE,OAAM;gDAA6BC,OAAM;gDAAKC,QAAO;gDAAKC,SAAQ;gDAAYC,MAAK;gDAAOC,QAAO;gDAAeC,aAAY;gDAAIC,eAAc;gDAAQC,gBAAe;;kEAAQ,6LAAC;wDAAKE,GAAE;wDAAIC,GAAE;wDAAIV,OAAM;wDAAKC,QAAO;wDAAKU,IAAG;wDAAIC,IAAG;;;;;;kEAAW,6LAAC;wDAAKJ,GAAE;;;;;;kEAAyD,6LAAC;wDAAKK,IAAG;wDAAOC,IAAG;wDAAMC,IAAG;wDAAQC,IAAG;;;;;;;;;;;;;;;;;sDAE1V,6LAAC;4CAAElB,MAAK;4CAAI,cAAW;4CAAUD,WAAU;sDACzC,cAAA,6LAAC;gDAAIE,OAAM;gDAA6BC,OAAM;gDAAKC,QAAO;gDAAKC,SAAQ;gDAAYC,MAAK;gDAAOC,QAAO;gDAAeC,aAAY;gDAAIC,eAAc;gDAAQC,gBAAe;0DAAQ,cAAA,6LAAC;oDAAKC,GAAE;;;;;;;;;;;;;;;;;;;;;;8CAG9L,6LAAC;oCAAEX,WAAU;8CAAyB;;;;;;;;;;;;;;;;;;8BAI1C,6LAAC;oBAAIA,WAAU;;sCACb,6LAAC;4BAAEA,WAAU;;gCAAyB;gCACjC,IAAIoB,OAAOC,WAAW;gCAAG;;;;;;;sCAE9B,6LAAC;4BAAIrB,WAAU;;8CACb,6LAAC,0KAAI;oCAACC,MAAK;oCAAID,WAAU;8CAA8C;;;;;;8CACvE,6LAAC,0KAAI;oCAACC,MAAK;oCAAID,WAAU;8CAA8C;;;;;;8CACvE,6LAAC,0KAAI;oCAACC,MAAK;oCAAID,WAAU;8CAA8C;;;;;;;;;;;;;;;;;;;;;;;;;;;;;AAMnF;KAjEwBD"}},
    {"offset": {"line": 458, "column": 0}, "map": {"version":3,"sources":["file:///D:/FINAL-Ano-Tara/ano-tara/frontend/app/page.js"],"sourcesContent":["\"use client\";\r\nimport React, { useState } from \"react\";\r\nimport Link from \"next/link\";\r\nimport Footer from \"./footer/Footer\";\r\n\r\nexport default function Home() {\r\n  const [guests, setGuests] = useState(3);\r\n  const [checkIn, setCheckIn] = useState(\"\");\r\n\r\n  const handleMinus = (e) => {\r\n    e.preventDefault();\r\n    setGuests((prev) => (prev > 1 ? prev - 1 : 1));\r\n  };\r\n\r\n  const handlePlus = (e) => {\r\n    e.preventDefault();\r\n    setGuests((prev) => prev + 1);\r\n  };\r\n\r\n  const searchUrl = `/destinations?date=${checkIn}&guests=${guests}`;\r\n\r\n  const saveTripSearch = () => {\r\n    const existing = JSON.parse(window.localStorage.getItem(\"anoTaraTrip\") || \"{}\");\r\n    window.localStorage.setItem(\"anoTaraTrip\", JSON.stringify({\r\n      ...existing,\r\n      targetDates: checkIn ? [checkIn] : [],\r\n      guests,\r\n    }));\r\n  };\r\n\r\n  return (\r\n    <main className=\"min-h-screen bg-[#FAFAFA]\">\r\n      \r\n      {/* --- HERO SECTION --- */}\r\n      <section className=\"relative flex min-h-[500px] w-full flex-col bg-[url('https://images.unsplash.com/photo-1507525428034-b723cf961d3e?auto=format&fit=crop&w=1800&q=80')] bg-cover bg-center\">\r\n        \r\n        <div className=\"absolute inset-0 bg-black/40\"></div>\r\n\r\n        {/* ORIGINAL TOP NAVIGATION (Transparent, shown at top of page) */}\r\n        <nav className=\"relative z-20 mx-auto flex w-full items-center justify-between px-6 py-4 sm:px-12\">\r\n          <div className=\"flex-1 hidden md:block\"></div>\r\n\r\n          <div className=\"flex flex-1 justify-center\">\r\n            <img src=\"/ano_tara_logo.svg\" alt=\"Ano Tara Logo\" className=\"h-20 w-20 drop-shadow-lg\" />\r\n          </div>\r\n\r\n          <div className=\"flex flex-1 items-center justify-end gap-3\">\r\n            <Link href=\"/predict-outfit\" className=\"rounded-md border border-white/60 bg-black/20 px-5 py-2 text-sm font-semibold text-white backdrop-blur-sm transition hover:bg-white/10\">\r\n              Outfit Planner\r\n            </Link>\r\n            <Link href=\"/final-planner\" className=\"rounded-md border border-white/60 bg-black/20 px-5 py-2 text-sm font-semibold text-white backdrop-blur-sm transition hover:bg-white/10\">\r\n              Planner\r\n            </Link>\r\n            <Link href=\"/\" className=\"flex items-center gap-2 rounded-md bg-white px-5 py-2 text-sm font-bold text-red-500 shadow-sm transition hover:bg-gray-100\">\r\n              <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"2.5\" strokeLinecap=\"round\" strokeLinejoin=\"round\"><path d=\"M19 21v-2a4 4 0 0 0-4-4H9a4 4 0 0 0-4 4v2\"/><circle cx=\"12\" cy=\"7\" r=\"4\"/></svg>\r\n              Sign up\r\n            </Link>\r\n          </div>\r\n        </nav>\r\n\r\n        {/* HERO MAIN TEXT */}\r\n        <div className=\"relative z-10 mx-auto flex flex-1 w-full max-w-5xl flex-col items-center justify-center px-5 pb-20 text-center text-white uppercase\">\r\n          <h1 className=\"text-6xl tracking-wide font-bold drop-shadow-lg sm:text-8xl mt-4\">\r\n            Travel, Ano tara?\r\n          </h1>\r\n          <p className=\"mt-5 text-4xl font-medium drop-shadow-md sm:text-6xl\">\r\n            kung saan maganda, mahal!\r\n          </p>\r\n        </div>\r\n      </section>\r\n\r\n      {/* --- ORIGINAL BIG SEARCH BAR (Floating in original position) --- */}\r\n      <div className=\"relative z-30 mx-auto -mt-12 w-[92%] max-w-4xl rounded-full border border-gray-200 bg-white p-2 sm:p-3 text-slate-900 shadow-[0_18px_40px_rgba(15,23,42,0.12)]\">\r\n        <div className=\"flex flex-col sm:flex-row gap-2 items-center px-2\">\r\n          \r\n          <div className=\"flex-[3] flex items-center w-full px-4 py-2 sm:border-r sm:border-slate-300 hover:bg-gray-50 rounded-2xl transition-colors cursor-pointer\">\r\n            <div className=\"flex-1\">\r\n              <p className=\"text-[11px] font-bold uppercase tracking-wider text-slate-500\">Travel date</p>\r\n              <input type=\"date\" value={checkIn} onChange={(event) => setCheckIn(event.target.value)} className=\"mt-1 w-full border-0 bg-transparent p-0 text-base font-medium text-slate-900 outline-none cursor-pointer\" />\r\n            </div>\r\n          </div>\r\n\r\n          <div className=\"flex-[1.5] flex flex-col justify-center w-full px-4 py-2 hover:bg-gray-50 rounded-2xl transition-colors\">\r\n            <p className=\"text-[11px] font-bold uppercase tracking-wider text-slate-500 mb-1\">Guests</p>\r\n            <div className=\"flex items-center justify-between\">\r\n              <button onClick={handleMinus} type=\"button\" className=\"flex h-7 w-7 items-center justify-center rounded-full border border-slate-300 text-slate-600 hover:border-slate-800 hover:text-slate-900 transition-colors\">\r\n                <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"2.5\" strokeLinecap=\"round\" strokeLinejoin=\"round\"><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"></line></svg>\r\n              </button>\r\n              \r\n              <span className=\"text-lg font-medium text-slate-900 w-8 text-center\">{guests}</span>\r\n              \r\n              <button onClick={handlePlus} type=\"button\" className=\"flex h-7 w-7 items-center justify-center rounded-full border border-slate-300 text-slate-600 hover:border-slate-800 hover:text-slate-900 transition-colors\">\r\n                <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"2.5\" strokeLinecap=\"round\" strokeLinejoin=\"round\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"></line><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"></line></svg>\r\n              </button>\r\n            </div>\r\n          </div>\r\n\r\n          <div className=\"flex-none w-full sm:w-auto mt-2 sm:mt-0 pl-2\">\r\n            <Link onClick={saveTripSearch} href={searchUrl} className=\"flex w-full items-center justify-center gap-2 rounded-full bg-[#b9f0c8] px-8 py-4 sm:py-5 shadow-sm transition hover:scale-105 active:scale-95 text-teal-950\">\r\n              <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"3\" strokeLinecap=\"round\" strokeLinejoin=\"round\"><circle cx=\"11\" cy=\"11\" r=\"8\"></circle><line x1=\"21\" y1=\"21\" x2=\"16.65\" y2=\"16.65\"></line></svg>\r\n              <span className=\"font-bold text-lg hidden sm:block\">Search</span>\r\n            </Link>\r\n          </div>\r\n\r\n        </div>\r\n      </div>\r\n\r\n      {/* --- SEARCH BY EXPERIENCE SECTION --- */}\r\n      <section className=\"mx-auto max-w-6xl px-4 py-20 sm:px-6\">\r\n        <div className=\"text-center mb-12\">\r\n          <h2 className=\"text-3xl font-bold text-slate-900 sm:text-4xl\">Search by experience type</h2>\r\n          <p className=\"mt-4 text-slate-500 max-w-2xl mx-auto\">\r\n            Looking for a relaxing beach side, or maybe just a city tour? Use the categories below to search for the experience that's right for you.\r\n          </p>\r\n        </div>\r\n\r\n        <div className=\"grid grid-cols-1 md:grid-cols-2 gap-6\">\r\n          <Link href=\"/destinations\" className=\"relative h-[26rem] rounded-3xl overflow-hidden group cursor-pointer shadow-md block\">\r\n            <img src=\"https://images.unsplash.com/photo-1499793983690-e29da59ef1c2?auto=format&fit=crop&w=800&q=80\" alt=\"Beach\" className=\"absolute inset-0 w-full h-full object-cover transition-transform duration-700 group-hover:scale-105\" />\r\n            <div className=\"absolute inset-0 bg-gradient-to-t from-[#1a1a2e]/90 via-[#1a1a2e]/40 to-transparent\" />\r\n            \r\n            <div className=\"absolute bottom-6 left-6 right-6 flex items-center gap-4\">\r\n              <div className=\"h-14 w-14 rounded-2xl bg-[#e4f7ed] flex items-center justify-center text-teal-800 shadow-lg\">\r\n                <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"2\" strokeLinecap=\"round\" strokeLinejoin=\"round\"><path d=\"M2 12h20\"/><path d=\"M12 2v20\"/><path d=\"M4.93 4.93l14.14 14.14\"/><path d=\"M19.07 4.93L4.93 19.07\"/></svg>\r\n              </div>\r\n              <div>\r\n                <h3 className=\"text-xl font-bold text-white\">Beach</h3>\r\n                <p className=\"text-sm text-slate-300\">16 experiences</p>\r\n              </div>\r\n            </div>\r\n          </Link>\r\n\r\n          <Link href=\"/destinations\" className=\"relative h-[26rem] rounded-3xl overflow-hidden group cursor-pointer shadow-md block\">\r\n            <img src=\"https://images.unsplash.com/photo-1518398046578-8cca57782e17?auto=format&fit=crop&w=800&q=80\" alt=\"City Tour\" className=\"absolute inset-0 w-full h-full object-cover transition-transform duration-700 group-hover:scale-105\" />\r\n            <div className=\"absolute inset-0 bg-gradient-to-t from-[#1a1a2e]/90 via-[#1a1a2e]/40 to-transparent\" />\r\n            \r\n            <div className=\"absolute bottom-6 left-6 right-6 flex items-center gap-4\">\r\n              <div className=\"h-14 w-14 rounded-2xl bg-[#e4f7ed] flex items-center justify-center text-teal-800 shadow-lg\">\r\n                <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"2\" strokeLinecap=\"round\" strokeLinejoin=\"round\"><path d=\"M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2\"></path><circle cx=\"9\" cy=\"7\" r=\"4\"></circle><path d=\"M23 21v-2a4 4 0 0 0-3-3.87\"></path><path d=\"M16 3.13a4 4 0 0 1 0 7.75\"></path></svg>\r\n              </div>\r\n              <div>\r\n                <h3 className=\"text-xl font-bold text-white\">City Tour</h3>\r\n                <p className=\"text-sm text-slate-300\">14 experiences</p>\r\n              </div>\r\n            </div>\r\n          </Link>\r\n        </div>\r\n        \r\n        <div className=\"mt-16 flex justify-center\">\r\n          <Link href=\"/all-experiences\" className=\"rounded-lg border-2 border-red-400 px-8 py-3 font-semibold text-red-500 transition hover:bg-red-50\">\r\n            View All Experiences\r\n          </Link>\r\n        </div>\r\n      </section>\r\n\r\n      {/* --- OUTFIT PLANNER CTA --- */}\r\n      <section className=\"mx-auto max-w-6xl px-4 pb-20 sm:px-6\">\r\n        <div className=\"overflow-hidden rounded-3xl bg-[#eef6f1] shadow-sm\">\r\n          <div className=\"grid items-center gap-8 lg:grid-cols-2\">\r\n            <div className=\"px-8 py-12 sm:px-12\">\r\n              <h2 className=\"font-serif text-4xl font-black tracking-wide text-slate-900 sm:text-5xl\">\r\n                Ano? Tara?\r\n              </h2>\r\n              <p className=\"mt-4 max-w-md text-base leading-relaxed text-slate-600 sm:text-lg\">\r\n                Try our outfit matcher to see if your outfit is fit for the day and destination you want to go!\r\n              </p>\r\n              <Link\r\n                href=\"/predict-outfit\"\r\n                className=\"mt-8 inline-flex rounded-full bg-[#b9f0c8] px-8 py-3.5 font-bold text-slate-900 shadow-sm transition hover:-translate-y-0.5 hover:brightness-95\"\r\n              >\r\n                Try Outfit Matcher\r\n              </Link>\r\n            </div>\r\n            <div className=\"grid grid-cols-3 gap-2 p-4 sm:gap-3 sm:p-6 lg:min-h-[320px]\">\r\n              <img\r\n                src=\"https://images.unsplash.com/photo-1489987707025-afc232f7ea0f?auto=format&fit=crop&w=600&q=80\"\r\n                alt=\"Casual shirts on a rack\"\r\n                className=\"h-40 w-full rounded-2xl object-cover sm:h-full sm:min-h-[280px]\"\r\n              />\r\n              <img\r\n                src=\"https://images.unsplash.com/photo-1490481651871-ab68de25d43d?auto=format&fit=crop&w=600&q=80\"\r\n                alt=\"Travel-ready clothing flat lay\"\r\n                className=\"h-40 w-full rounded-2xl object-cover sm:h-full sm:min-h-[280px]\"\r\n              />\r\n              <img\r\n                src=\"https://images.unsplash.com/photo-1434389677669-e08b4cac3105?auto=format&fit=crop&w=600&q=80\"\r\n                alt=\"Layered coat and outfit pieces\"\r\n                className=\"h-40 w-full rounded-2xl object-cover sm:h-full sm:min-h-[280px]\"\r\n              />\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </section>\r\n\r\n      {/* --- FULL-WIDTH PROMO BANNER SECTION --- */}\r\n      <section className=\"relative w-full overflow-hidden bg-slate-900 shadow-lg min-h-[500px] flex items-center\">\r\n        <img src=\"https://images.unsplash.com/photo-1507525428034-b723cf961d3e?auto=format&fit=crop&w=2400&q=80\" alt=\"Promo Background\" className=\"absolute inset-0 h-full w-full object-cover grayscale opacity-80\" />\r\n        <div className=\"absolute inset-0 bg-gradient-to-r from-black/80 via-black/50 to-transparent\" />\r\n\r\n        <div className=\"relative z-10 mx-auto w-full max-w-6xl px-6 py-16 sm:px-12\">\r\n          <div className=\"flex w-full flex-col items-start md:w-3/4 lg:w-1/2\">\r\n            <h2 className=\"mb-3 font-serif text-4xl font-black tracking-wide text-white drop-shadow-md sm:text-5xl\">\r\n              Adventure Awaits. <br className=\"hidden sm:block\" /> Tara Na!\r\n            </h2>\r\n\r\n            <p className=\"pt-4 mb-10 text-base leading-relaxed text-gray-300 drop-shadow-sm sm:text-lg\">\r\n              Stop dreaming and start packing. From sun-kissed local beaches to vibrant cityscapes across the map, explore top-rated destinations tailored for your budget and style. Your next unforgettable story begins right here.\r\n            </p>\r\n            <Link href=\"/destinations\">\r\n              <button className=\"rounded-full bg-[#b9f0c8] px-10 py-4 font-bold text-slate-900 shadow-[0_4px_14px_0_rgba(185,240,200,0.39)] transition hover:-translate-y-1 hover:shadow-[0_6px_20px_rgba(185,240,200,0.23)] active:translate-y-0\">\r\n                Start Exploring Now\r\n              </button>\r\n            </Link>\r\n          </div>\r\n        </div>\r\n      </section>\r\n\r\n      <Footer />\r\n    </main>\r\n  );\r\n}\r\n"],"names":["Home","guests","setGuests","checkIn","setCheckIn","handleMinus","e","preventDefault","prev","handlePlus","searchUrl","saveTripSearch","existing","JSON","parse","window","localStorage","getItem","setItem","stringify","targetDates","className","src","alt","href","xmlns","width","height","viewBox","fill","stroke","strokeWidth","strokeLinecap","strokeLinejoin","d","cx","cy","r","type","value","onChange","event","target","onClick","x1","y1","x2","y2"],"mappings":";;;;;AACA;AACA;AACA;;;AAHA;;;;AAKe,SAASA;;IACtB,MAAM,CAACC,QAAQC,UAAU,GAAG,IAAA,yKAAQ,EAAC;IACrC,MAAM,CAACC,SAASC,WAAW,GAAG,IAAA,yKAAQ,EAAC;IAEvC,MAAMC,cAAc,CAACC;QACnBA,EAAEC,cAAc;QAChBL,UAAU,CAACM,OAAUA,OAAO,IAAIA,OAAO,IAAI;IAC7C;IAEA,MAAMC,aAAa,CAACH;QAClBA,EAAEC,cAAc;QAChBL,UAAU,CAACM,OAASA,OAAO;IAC7B;IAEA,MAAME,YAAY,CAAC,mBAAmB,EAAEP,QAAQ,QAAQ,EAAEF,QAAQ;IAElE,MAAMU,iBAAiB;QACrB,MAAMC,WAAWC,KAAKC,KAAK,CAACC,OAAOC,YAAY,CAACC,OAAO,CAAC,kBAAkB;QAC1EF,OAAOC,YAAY,CAACE,OAAO,CAAC,eAAeL,KAAKM,SAAS,CAAC;YACxD,GAAGP,QAAQ;YACXQ,aAAajB,UAAU;gBAACA;aAAQ,GAAG,EAAE;YACrCF;QACF;IACF;IAEA,qBACE,6LAAC;QAAKoB,WAAU;;0BAGd,6LAAC;gBAAQA,WAAU;;kCAEjB,6LAAC;wBAAIA,WAAU;;;;;;kCAGf,6LAAC;wBAAIA,WAAU;;0CACb,6LAAC;gCAAIA,WAAU;;;;;;0CAEf,6LAAC;gCAAIA,WAAU;0CACb,cAAA,6LAAC;oCAAIC,KAAI;oCAAqBC,KAAI;oCAAgBF,WAAU;;;;;;;;;;;0C